assert.strictEqual(pr.state, 'Open');
assert.strictEqual(pr.base, 'main');
assert.strictEqual(pr.compare, 'feature-search');
var head = ARC.state.branches.filter(function (b) { return b.repoId === 'r1' && b.name === 'feature-search'; })[0];
