assert.ok(ARC.state.grants.some(function (g) { return g.repoId === 'r1' && g.subjectId === 'u2' && g.role === 'Write'; }));
assert.strictEqual(ARC.state.reviews.length, 1);
assert.strictEqual(ARC.state.reviews[0].state, 'Changes requested');
assert.strictEqual(ARC.state.reviews[0].commitId, 'c1');

proposed.check:
var repo = ARC.state.repositories.filter(function (r) { return r.id === 'r1'; })[0];
var pr = ARC.state.pulls.filter(function (p) { return p.id === 'p1'; })[0];
